	XSDNS  = "http://www.w3.org/2001/XMLSchema"
	SOAPNS = "http://schemas.xmlsoap.org/wsdl/soap/"
	HTTPNS = "http://schemas.xmlsoap.org/wsdl/http/"
)

type Definitions struct {
	XMLName           xml.Name  `xml:"http://schemas.xmlsoap.org/wsdl/ definitions"`
	TargetNamespace   string    `xml:"targetNamespace,attr"`
	Name              string    `xml:"name,attr"`
	Types             Types     `xml:"http://schemas.xmlsoap.org/wsdl/ types"`
	Messages          []Message `xml:"http://schemas.xmlsoap.org/wsdl/ message"`
	PortTypes         []PortType `xml:"http://schemas.xmlsoap.org/wsdl/ portType"`
	Bindings          []Binding `xml:"http://schemas.xmlsoap.org/wsdl/ binding"`
	Services          []Service `xml:"http://schemas.xmlsoap.org/wsdl/ service"`
	Imports           []WSDLImport `xml:"http://schemas.xmlsoap.org/wsdl/ import"`
}

type WSDLImport struct {
	Namespace string `xml:"namespace,attr"`
	Location  string `xml:"location,attr"`
}

type Types struct {
	Schemas []Schema `xml:"http://www.w3.org/2001/XMLSchema schema"`
	// Also handle schema without prefix? Already via NS
	// For WSDLs with <types><schema> where schema has no NS? stock.wsdl has <schema> without prefix but with xmlns=XSDNS, so it has NS
	// Need also handle <types> with direct? No
}

type Schema struct {
	XMLName             xml.Name     `xml:"http://www.w3.org/2001/XMLSchema schema"`
	TargetNamespace     string       `xml:"targetNamespace,attr"`
	ElementFormDefault  string       `xml:"elementFormDefault,attr"`
	AttributeFormDefault string      `xml:"attributeFormDefault,attr"`
	Elements            []Element    `xml:"http://www.w3.org/2001/XMLSchema element"`
	ComplexTypes        []ComplexType `xml:"http://www.w3.org/2001/XMLSchema complexType"`
	SimpleTypes         []SimpleType `xml:"http://www.w3.org/2001/XMLSchema simpleType"`
	Attributes          []Attribute  `xml:"http://www.w3.org/2001/XMLSchema attribute"`
	Imports             []SchemaImport `xml:"http://www.w3.org/2001/XMLSchema import"`
	Includes            []SchemaImport `xml:"http://www.w3.org/2001/XMLSchema include"`
}

type SchemaImport struct {
	Namespace      string `xml:"namespace,attr"`
	SchemaLocation string `xml:"schemaLocation,attr"`
}

type Element struct {
	XMLName      xml.Name    `xml:"http://www.w3.org/2001/XMLSchema element"`
	Name         string      `xml:"name,attr"`
	Type         string      `xml:"type,attr"`
	Ref          string      `xml:"ref,attr"`
	MinOccurs    string      `xml:"minOccurs,attr"`
	MaxOccurs    string      `xml:"maxOccurs,attr"`
	Nillable     string      `xml:"nillable,attr"`
	Annotation   Annotation  `xml:"http://www.w3.org/2001/XMLSchema annotation"`
	ComplexType  *ComplexType `xml:"http://www.w3.org/2001/XMLSchema complexType"`
	SimpleType   *SimpleType  `xml:"http://www.w3.org/2001/XMLSchema simpleType"`
}

type ComplexType struct {
	XMLName        xml.Name       `xml:"http://www.w3.org/2001/XMLSchema complexType"`
	Name           string         `xml:"name,attr"`
	Annotation     Annotation     `xml:"http://www.w3.org/2001/XMLSchema annotation"`
	Sequence       *Sequence      `xml:"http://www.w3.org/2001/XMLSchema sequence"`
	All            *Sequence      `xml:"http://www.w3.org/2001/XMLSchema all"`
	Choice         *Sequence      `xml:"http://www.w3.org/2001/XMLSchema choice"`
	Attributes     []Attribute    `xml:"http://www.w3.org/2001/XMLSchema attribute"`
	AttributeGroups []AttributeGroup `xml:"http://www.w3.org/2001/XMLSchema attributeGroup"`
	SimpleContent  *SimpleContent `xml:"http://www.w3.org/2001/XMLSchema simpleContent"`
	ComplexContent *ComplexContent `xml:"http://www.w3.org/2001/XMLSchema complexContent"`
	AnyAttribute   *AnyAttribute  `xml:"http://www.w3.org/2001/XMLSchema anyAttribute"`
	Any            *Any           `xml:"http://www.w3.org/2001/XMLSchema any"`
	// For handling <complexType/> empty (no children) - will have nils
}

type AttributeGroup struct {
	XMLName xml.Name `xml:"http://www.w3.org/2001/XMLSchema attributeGroup"`
	Ref     string   `xml:"ref,attr"`
}

type AnyAttribute struct {
	XMLName xml.Name `xml:"http://www.w3.org/2001/XMLSchema anyAttribute"`
}

type Any struct {
	XMLName xml.Name `xml:"http://www.w3.org/2001/XMLSchema any"`
}

type Sequence struct {
	XMLName  xml.Name  `xml:""`
	Elements []Element `xml:"http://www.w3.org/2001/XMLSchema element"`
	Choices  []Sequence `xml:"http://www.w3.org/2001/XMLSchema choice"`
	Sequences []Sequence `xml:"http://www.w3.org/2001/XMLSchema sequence"`
	Anys     []Any     `xml:"http://www.w3.org/2001/XMLSchema any"`
}

// Need separate for all/choice? Use same struct

type SimpleContent struct {
	XMLName   xml.Name   `xml:"http://www.w3.org/2001/XMLSchema simpleContent"`
	Extension *Extension `xml:"http://www.w3.org/2001/XMLSchema extension"`
	Restriction *Restriction `xml:"http://www.w3.org/2001/XMLSchema restriction"`
}

type ComplexContent struct {
	XMLName   xml.Name   `xml:"http://www.w3.org/2001/XMLSchema complexContent"`
	Extension *Extension `xml:"http://www.w3.org/2001/XMLSchema extension"`
	Restriction *Restriction `xml:"http://www.w3.org/2001/XMLSchema restriction"`
}

type Extension struct {
	XMLName    xml.Name    `xml:"http://www.w3.org/2001/XMLSchema extension"`
	Base       string      `xml:"base,attr"`
	Sequence   *Sequence   `xml:"http://www.w3.org/2001/XMLSchema sequence"`
	All        *Sequence   `xml:"http://www.w3.org/2001/XMLSchema all"`
	Choice     *Sequence   `xml:"http://www.w3.org/2001/XMLSchema choice"`
	Attributes []Attribute `xml:"http://www.w3.org/2001/XMLSchema attribute"`
	AnyAttribute *AnyAttribute `xml:"http://www.w3.org/2001/XMLSchema anyAttribute"`
}

type SimpleType struct {
	XMLName     xml.Name     `xml:"http://www.w3.org/2001/XMLSchema simpleType"`
	Name        string       `xml:"name,attr"`
	Annotation  Annotation   `xml:"http://www.w3.org/2001/XMLSchema annotation"`
	Restriction *Restriction `xml:"http://www.w3.org/2001/XMLSchema restriction"`
	List        *List        `xml:"http://www.w3.org/2001/XMLSchema list"`
	Union       *Union       `xml:"http://www.w3.org/2001/XMLSchema union"`
}

type List struct {
	XMLName xml.Name `xml:"http://www.w3.org/2001/XMLSchema list"`
	ItemType string `xml:"itemType,attr"`
}

type Union struct {
	XMLName xml.Name `xml:"http://www.w3.org/2001/XMLSchema union"`
}

type Restriction struct {
	XMLName      xml.Name      `xml:"http://www.w3.org/2001/XMLSchema restriction"`
	Base         string        `xml:"base,attr"`
	Enumerations []Enumeration `xml:"http://www.w3.org/2001/XMLSchema enumeration"`
	// Other facets like minLength, etc. ignored
	Sequence     *Sequence     `xml:"http://www.w3.org/2001/XMLSchema sequence"`
	Attributes   []Attribute   `xml:"http://www.w3.org/2001/XMLSchema attribute"`
}

type Enumeration struct {
	XMLName    xml.Name   `xml:"http://www.w3.org/2001/XMLSchema enumeration"`
	Value      string     `xml:"value,attr"`
	Annotation Annotation `xml:"http://www.w3.org/2001/XMLSchema annotation"`
}

type Attribute struct {
	XMLName    xml.Name    `xml:"http://www.w3.org/2001/XMLSchema attribute"`
	Name       string      `xml:"name,attr"`
	Ref        string      `xml:"ref,attr"`
	Type       string      `xml:"type,attr"`
	Use        string      `xml:"use,attr"`
	Annotation Annotation  `xml:"http://www.w3.org/2001/XMLSchema annotation"`
	SimpleType *SimpleType `xml:"http://www.w3.org/2001/XMLSchema simpleType"`
}

type Annotation struct {
	XMLName       xml.Name `xml:"http://www.w3.org/2001/XMLSchema annotation"`
	Documentation []Documentation `xml:"http://www.w3.org/2001/XMLSchema documentation"`
}

type Documentation struct {
	XMLName xml.Name `xml:"http://www.w3.org/2001/XMLSchema documentation"`
	Text    string   `xml:",chardata"`
}

type Message struct {
	XMLName xml.Name `xml:"http://schemas.xmlsoap.org/wsdl/ message"`
	Name    string   `xml:"name,attr"`
	Parts   []Part   `xml:"http://schemas.xmlsoap.org/wsdl/ part"`
}

type Part struct {
	XMLName xml.Name `xml:"http://schemas.xmlsoap.org/wsdl/ part"`
	Name    string   `xml:"name,attr"`
	Element string   `xml:"element,attr"`
	Type    string   `xml:"type,attr"`
}

type PortType struct {
	XMLName    xml.Name    `xml:"http://schemas.xmlsoap.org/wsdl/ portType"`
	Name       string      `xml:"name,attr"`
	Operations []Operation `xml:"http://schemas.xmlsoap.org/wsdl/ operation"`
}

type Operation struct {
	XMLName       xml.Name        `xml:"http://schemas.xmlsoap.org/wsdl/ operation"`
	Name          string          `xml:"name,attr"`
	Documentation string          `xml:"http://schemas.xmlsoap.org/wsdl/ documentation"`
	Input         *OpInputOutput  `xml:"http://schemas.xmlsoap.org/wsdl/ input"`
	Output        *OpInputOutput  `xml:"http://schemas.xmlsoap.org/wsdl/ output"`
	Fault         *OpInputOutput  `xml:"http://schemas.xmlsoap.org/wsdl/ fault"`
}

type OpInputOutput struct {
	XMLName xml.Name `xml:""`
	Message string   `xml:"message,attr"`
	Name    string   `xml:"name,attr"`
}

type Binding struct {
	XMLName    xml.Name           `xml:"http://schemas.xmlsoap.org/wsdl/ binding"`
	Name       string             `xml:"name,attr"`
	Type       string             `xml:"type,attr"`
	SoapBinding *SoapBinding      `xml:"http://schemas.xmlsoap.org/wsdl/soap/ binding"`
	HttpBinding *HttpBinding      `xml:"http://schemas.xmlsoap.org/wsdl/http/ binding"`
	Operations []BindingOperation `xml:"http://schemas.xmlsoap.org/wsdl/ operation"`
}

type SoapBinding struct {
	XMLName   xml.Name `xml:"http://schemas.xmlsoap.org/wsdl/soap/ binding"`
	Style     string   `xml:"style,attr"`
	Transport string   `xml:"transport,attr"`
}

type HttpBinding struct {
	XMLName xml.Name `xml:"http://schemas.xmlsoap.org/wsdl/http/ binding"`
	Verb    string   `xml:"verb,attr"`
}

type BindingOperation struct {
	XMLName       xml.Name            `xml:"http://schemas.xmlsoap.org/wsdl/ operation"`
	Name          string              `xml:"name,attr"`
	SoapOperation *SoapOperation      `xml:"http://schemas.xmlsoap.org/wsdl/soap/ operation"`
	Input         *BindingIO          `xml:"http://schemas.xmlsoap.org/wsdl/ input"`
	Output        *BindingIO          `xml:"http://schemas.xmlsoap.org/wsdl/ output"`
}

type SoapOperation struct {
	XMLName    xml.Name `xml:"http://schemas.xmlsoap.org/wsdl/soap/ operation"`
	SoapAction string   `xml:"soapAction,attr"`
	Style      string   `xml:"style,attr"`
}

type BindingIO struct {
	XMLName  xml.Name  `xml:""`
	SoapBody *SoapBody `xml:"http://schemas.xmlsoap.org/wsdl/soap/ body"`
}

type SoapBody struct {
	XMLName xml.Name `xml:"http://schemas.xmlsoap.org/wsdl/soap/ body"`
	Use     string   `xml:"use,attr"`
}

type Service struct {
	XMLName xml.Name `xml:"http://schemas.xmlsoap.org/wsdl/ service"`
	Name    string   `xml:"name,attr"`
	Ports   []Port   `xml:"http://schemas.xmlsoap.org/wsdl/ port"`
	Documentation string `xml:"http://schemas.xmlsoap.org/wsdl/ documentation"`
}

type Port struct {
	XMLName     xml.Name     `xml:"http://schemas.xmlsoap.org/wsdl/ port"`
	Name        string       `xml:"name,attr"`
	Binding     string       `xml:"binding,attr"`
	SoapAddress *SoapAddress `xml:"http://schemas.xmlsoap.org/wsdl/soap/ address"`
}

type SoapAddress struct {
	XMLName  xml.Name `xml:"http://schemas.xmlsoap.org/wsdl/soap/ address"`
	Location string   `xml:"location,attr"`
}
