package main

import (
	"strings"
	"unicode"
)

var goKeywords = map[string]bool{
	"break": true, "default": true, "func": true, "interface": true, "select": true,
	"case": true, "defer": true, "go": true, "map": true, "struct": true,
	"chan": true, "else": true, "goto": true, "package": true, "switch": true,
	"const": true, "fallthrough": true, "if": true, "range": true, "type": true,
	"continue": true, "for": true, "import": true, "return": true, "var": true,
}

func sanitize(name string) string {
	// Replace -, ., /, : with handling?
	// Observed: my-field -> My_field (dash to underscore)
	// my.field -> My_field (dot to underscore)
	// my field -> Myfield (space removed, next not capitalized? Actually my field -> Myfield (space removed))
	// a/b -> Ab (slash removed, next capitalized)
	// a:b -> Ab (colon removed, next capitalized)
	// Need to infer: likely code does strings.Replace for some chars, and handles others?
	// Let's implement: replace "-" and "." with "_", remove " ", "/", ":" but capitalize next?
	// For simplicity, implement as: iterate runes, if alphanumeric or "_" keep, else handle
	var b strings.Builder
	capitalizeNext := false
	for i, r := range name {
		if (r >= 'A' && r <= 'Z') || (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '_' {
			if capitalizeNext {
				b.WriteRune(unicode.ToUpper(r))
				capitalizeNext = false
			} else {
				b.WriteRune(r)
			}
			_ = i
		} else if r == '-' || r == '.' {
			b.WriteRune('_')
			capitalizeNext = false
		} else if r == '/' || r == ':' {
			// remove and capitalize next?
			capitalizeNext = true
		} else if r == ' ' {
			// remove, do not capitalize? For "my field" -> "Myfield" (f lower), so not capitalize
			// But for "a/b" -> "Ab" (b upper), so slash does capitalize
			// So space: just remove
		} else {
			// For other chars, replace with "_"?
			b.WriteRune('_')
		}
	}
	s := b.String()
	// Handle Go keywords: append "_"
	if goKeywords[strings.ToLower(s)] || goKeywords[s] {
		// Original: "type" -> "Type_", "func" -> "Func_", "return" -> "Return_", "Range" -> "Range" (not keyword? Range is not keyword, so no suffix)
		// Check: "Range" is not keyword, so no suffix. Our map has lowercase, so "Range" lower is "range" which is keyword, but original "Range" did NOT get suffix (stayed "Range").
		// So check case-sensitive? "Range" vs "range" - original kept "Range" without suffix, so it's case-sensitive.
		// "return_" -> "Return_" (already has underscore, but still capitalized? Actually "return_" with true gave "Return_" - so it capitalizes and keeps underscore)
		// For keyword check, should be case-sensitive on original? "type" (lower) is keyword, "Type" (capital) is not.
		// So check exact s?
	}
	// Actually do keyword check case-sensitive on sanitized? For "type" sanitized is "type" (lower), which is keyword, so add "_"? But result was "Type_" (capital T + underscore). So steps: first make public? Then check keyword?
	// Let's handle keyword after public logic in caller
	return s
}

func makePublicName(name string, makePublic bool) string {
	s := sanitize(name)
	if s == "" {
		return s
	}
	// If starts with digit, leave as is (will cause gofmt error, as original)
	// If starts with "_", leave? For "_test" stays "_test" in both (as observed)
	if s[0] == '_' {
		return s
	}
	// Check if first char is letter?
	if makePublic {
		// Capitalize first letter
		r := []rune(s)
		r[0] = unicode.ToUpper(r[0])
		s = string(r)
	} else {
		// Preserve as is? For "myString" with false stays "myString" (lower m), for "MyString" stays "MyString"
		// So do nothing
	}
	// Handle keywords: if s is Go keyword (case-sensitive? "type" is keyword, "Type" is not)
	// Original: "type" with true gave "Type_" (capital + underscore). So after capitalizing, "type" -> "Type", then check if lower is keyword? Or check original?
	// "type" -> "Type" (capitalized), then "Type" is not keyword (case-sensitive), but it still got "_" suffix. So check must be case-insensitive or on original?
	// Let's check: "Range" (capital R) is not keyword, stayed "Range" (no suffix). "return" (lower) gave "Return_" (with suffix). "return_" gave "Return_" (with suffix, but already had underscore? Actually "return_" -> "Return_" (same, with underscore, capital R). So "return_" sanitized is "return_" (with underscore), capitalized is "Return_", which is not keyword, but it kept underscore (original had underscore, so not added). Hmm.
	// For "type": sanitized "type", capitalized "Type", which is not keyword, but got "_" suffix. So suffix was added even though "Type" is not keyword. Means check is case-insensitive? "type" lower is keyword, so add suffix.
	// For "Range": sanitized "Range", capitalized "Range", lower "range" is keyword, but it did NOT get suffix. So inconsistent.
	// Wait "Range" vs "range": "Range" capital R, lower "range" is keyword, but no suffix. While "type" lower "type" is keyword, got suffix. So why difference?
	// Maybe "Range" is considered as XSD type "Range" (custom) not keyword? Or maybe keyword check is exact (case-sensitive) on capitalized? "Type" vs "type": "Type" is not keyword, but it got suffix, so not exact.
	// Let's re-examine: "type" element with true gave "Type_" (with underscore). "Range" element? We didn't test "Range" as element name, we tested "Range" as? Actually we tested "Range" as element name? No, we tested "Range" as? In keyword test, "Range" gave "Range" (no suffix). That was element name "Range" (capital R) with true. "type" (lower) gave "Type_" (with suffix). So difference is original case: "type" lower vs "Range" capital. After capitalizing, both become "Type" vs "Range". "Type" got suffix, "Range" didn't. So suffix depends on original lower being keyword AND sanitized? But both lower are keywords ("type" and "range"). Why one gets suffix and other doesn't?
	// Maybe "Range" is not considered keyword because it's a type name in WSDL? No.
	// Let's test more: "range" (lower) as element name with true?
	return s
}

