func generate(wsdlContent []byte, baseDir string, baseURLStr string, rawWSDL string, isURL bool) error {
	// Parse main WSDL
	var def Definitions
	if err := xml.Unmarshal(wsdlContent, &def); err != nil {
		return err
	}
	// Collect schemas
