	// Need to preserve schema order and within-schema order
	var simpleList []*SimpleType
	var simpleNSList []string
	var elementList []*Element
	var elementNSList []string
	var complexList []*ComplexType
	var complexNSList []string
	// For deduplication tracking? Keep all, even duplicates? Original generates duplicates for duplicate names (as warned)
	// But for usda where element and complexType have same name, it generates only one (struct, not alias)? Let's handle that later
	for si := range gd.Schemas {
		s := &gd.Schemas[si]
