	buf.WriteString("package " + pkg + "\n\n")
	buf.WriteString("import (\n\t\"context\"\n\t\"encoding/xml\"\n\t\"github.com/hooklift/gowsdl/soap\"\n\t\"time\"\n)\n\n")
	buf.WriteString("// against \"unused imports\"\nvar _ time.Time\nvar _ xml.Name\n\n")
	buf.WriteString("type AnyType struct {\n\tInnerXML string `xml:\",innerxml\"`\n}\n\n")
	buf.WriteString("type AnyURI string\n\n")
	buf.WriteString("type NCName string\n\n")
	// For tracking which Go names already generated (to handle duplicates? Original generates duplicates, so don't dedup? But for usda same-name element+complex, need to skip alias?)
	// We'll generate simpleTypes first
	for idx, st := range simpleList {
		ns := simpleNSList[idx]
		_ = ns
		genSimpleType(&buf, st, makePublic)
	}
	// For elements: need to handle each element's type
	// Keep set of Go names for complexTypes to detect same-name alias skip?
	complexGoNames := map[string]bool{}
	for _, c := range complexList {
		gn := goName(c.Name, makePublic)
		complexGoNames[gn] = true
		// Also need lower? For case-insensitive? usda element getForecasts (lower g) vs complex getForecasts (lower g) -> both Go GetForecasts (same). So check Go names, not original.
	}
	// Also simple Go names?
	simpleGoNames := map[string]bool{}
	for _, st := range simpleList {
		gn := goName(st.Name, makePublic)
		simpleGoNames[gn] = true
	}
	for idx, e := range elementList {
		ns := elementNSList[idx]
		// Check if element's Go name equals a complex/simple Go name with same underlying? For usda, element getForecasts type tns:getForecasts (same local). Then skip alias?
		// Logic: if element has Type attribute and local of Type equals element Name (case-sensitive? Or Go names equal?), then skip alias (since struct will represent both)?
		// For ec2, element CreateImage type tns:CreateImageType (different), so not skip.
		// For usda, element getForecasts type tns:getForecasts (same), so skip.
		// Check Go names: element Go vs type local Go? For usda, both GetForecasts, so skip.
		eGo := goName(e.Name, makePublic)
		if e.Type != "" {
			tLocal := localName(e.Type)
			// If builtin? Then not skip (element with builtin type should generate alias? Like myString string -> alias, even though names differ? Actually element name myString vs type string (builtin) -> generate alias myString string. Good, not skip.
			if !isBuiltinType(e.Type) {
				tGoPublic := goName(tLocal, true) // alias target always public? But for skip check, use makePublic? For usda, both lower, Go names same regardless.
				tGo := goName(tLocal, makePublic)
				// If eGo == tGo or eGo == tGoPublic? For usda with makePublic true, both GetForecasts, so skip. With false, eGo = getForecasts? Wait element getForecasts with false: goName("getForecasts", false) = "getForecasts" (lower g), complex getForecasts with false: "getForecasts" (lower). So still equal, skip. Good.
				if eGo == tGo || eGo == tGoPublic {
					// Skip alias, since complexType struct will cover?
					// But need to ensure complexType exists? Check if tLocal in ComplexMap or SimpleMap?
					if _, ok := gd.ComplexMap[tLocal]; ok {
						continue
					}
					if _, ok := gd.SimpleMap[tLocal]; ok {
						continue
					}
					// Also check case where type is same but not found? Still skip? Probably.
					// For safety, if type not found, still skip? No, generate alias? Let's only skip if found.
				}
			}
		}
		genElement(&buf, e, ns, gd, makePublic)
	}
	for idx, c := range complexList {
		ns := complexNSList[idx]
		genComplexType(&buf, c, ns, gd, makePublic, elementList, elementNSList)
	}
	// Generate operations
	opCode, opWarns := genOperations(gd, makePublic)
	buf.WriteString(opCode)
	warns = append(warns, opWarns...)
	clientCode := buf.String()
	// Generate server code
	serverCode := genServer(gd, pkg, rawWSDL, makePublic)
	return clientCode, serverCode, warns
}

