func findXMLNameForComplex(complexName, complexNS string, gd *GenData, elementList []*Element, elementNSList []string) string {
	// Check qualified
	qualified := true
	if q, ok := gd.ElementFormQualified[complexNS]; ok {
		qualified = q
	} else {
		// If not found, check any? Default true (as for stock with no elementFormDefault)
		qualified = true
	}
	if !qualified {
		return ""
	}
	// Collect all refs (name, ns) for this complexType
	type ref struct{ name, ns string }
	var refs []ref
	for idx, e := range elementList {
		ns := elementNSList[idx]
		if e.Type != "" && localName(e.Type) == complexName {
			refs = append(refs, ref{e.Name, ns})
		}
	}
	// Nested refs: scan all complexTypes and inline element complexTypes
	for si := range gd.Schemas {
		s := &gd.Schemas[si]
		ns := s.TargetNamespace
		// Named complexTypes
		for _, ct := range s.ComplexTypes {
			for _, e := range collectAllNestedElements(&ct, nil) {
				if e.Type != "" && localName(e.Type) == complexName {
					refs = append(refs, ref{e.Name, ns})
				}
			}
			// Also extension?
			if ct.ComplexContent != nil && ct.ComplexContent.Extension != nil {
				ext := ct.ComplexContent.Extension
				if ext.Sequence != nil {
					for _, e := range ext.Sequence.Elements {
						if e.Type != "" && localName(e.Type) == complexName {
							refs = append(refs, ref{e.Name, ns})
						}
					}
				}
			}
		}
		// Top-level elements' inline
		for _, e := range s.Elements {
			if e.ComplexType != nil {
				for _, fe := range collectAllNestedElements(e.ComplexType, nil) {
					if fe.Type != "" && localName(fe.Type) == complexName {
						refs = append(refs, ref{fe.Name, ns})
					}
				}
			}
		}
	}
	if len(refs) == 0 {
		return ""
	}
	// Check unique names
	uniq := map[string]string{} // name+ns -> name
	for _, r := range refs {
		key := r.ns + " " + r.name
		uniq[key] = r.name
	}
	if len(uniq) != 1 {
		return ""
	}
	// Single unique name: check distance <=2 via BFS
	dist := computeDistance(complexName, gd, elementList)
	if dist > 2 {
		return ""
	}
	// Return the unique name
	for k := range uniq {
		return k
	}
	return ""
}

func collectAllNestedElements(ct *ComplexType, _ interface{}) []Element {
	var res []Element
	if ct.Sequence != nil {
		res = append(res, ct.Sequence.Elements...)
		// TODO: nested choices/sequences?
	}
	if ct.All != nil {
		res = append(res, ct.All.Elements...)
	}
	if ct.Choice != nil {
		res = append(res, ct.Choice.Elements...)
	}
	if ct.SimpleContent != nil {
		// No elements, only attributes? Ignore
	}
	if ct.ComplexContent != nil && ct.ComplexContent.Extension != nil {
		ext := ct.ComplexContent.Extension
		if ext.Sequence != nil {
			res = append(res, ext.Sequence.Elements...)
		}
		if ext.All != nil {
			res = append(res, ext.All.Elements...)
		}
		if ext.Choice != nil {
			res = append(res, ext.Choice.Elements...)
		}
	}
	return res
}

func computeDistance(target string, gd *GenData, elementList []*Element) int {
	// BFS from top-level elements (distance 0) following references
	// Build map: complexType name -> distance (shortest)
	// Initialize queue with top-level elements' referenced complexTypes? Actually top-level elements themselves are distance 0? For distance of complexType, if referenced directly by top-level element, distance 1.
	// Simplify: BFS where nodes are complexType names, edges from parent complexType/element to child.
	// Start: all top-level elements (as parents distance 0) -> their referenced complexTypes distance 1.
	// Then from each complexType at distance D, its referenced children distance D+1.
	// Need to handle inline element complexTypes? Those are not named, but their fields reference named types at distance 1? For ConfirmAppointment (inline, not named) referencing AppointmentInfo, AppointmentInfo distance 1. Good. So top-level elements with inline types should be considered as parents at distance 0.
	// Implementation: queue of (complexType name, distance) plus visited.
	// First, collect all top-level elements and their direct children.
	distMap := map[string]int{}
	queue := []string{}
	// Helper to add with distance
	add := func(name string, d int) {
		if prev, ok := distMap[name]; !ok || d < prev {
			distMap[name] = d
			queue = append(queue, name)
		}
	}
	// Initialize from top-level elements
	for _, e := range elementList {
		// If element has Type (named), then that type distance 1
		if e.Type != "" && !isBuiltinType(e.Type) {
			add(localName(e.Type), 1)
		}
		// If element has inline complexType, then its fields' referenced types distance 1
		if e.ComplexType != nil {
			for _, fe := range collectAllNestedElements(e.ComplexType, nil) {
				if fe.Type != "" && !isBuiltinType(fe.Type) {
					add(localName(fe.Type), 1)
				}
			}
		}
	}
	// BFS
	visited := map[string]bool{}
	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]
		if visited[cur] {
			continue
		}
		visited[cur] = true
		d := distMap[cur]
		// Find complexType definition for cur
		var ct *ComplexType
		for si := range gd.Schemas {
			for i := range gd.Schemas[si].ComplexTypes {
				if gd.Schemas[si].ComplexTypes[i].Name == cur {
					ct = &gd.Schemas[si].ComplexTypes[i]
					break
				}
			}
			if ct != nil {
				break
			}
		}
		if ct == nil {
			continue
		}
		for _, fe := range collectAllNestedElements(ct, nil) {
			if fe.Type != "" && !isBuiltinType(fe.Type) {
				child := localName(fe.Type)
				if _, ok := distMap[child]; !ok || d+1 < distMap[child] {
					distMap[child] = d + 1
					queue = append(queue, child)
				}
			}
		}
		// Also need to handle extension? Already in collect
	}
	if d, ok := distMap[target]; ok {
		return d
	}
	return 999
}
